require_once __DIR__.'/../includes/functions.php';$lessonId=(int)($_GET['lesson_id']??0);$stmt=$pdo->prepare('SELECT * FROM lessons WHERE id=? AND is_published=1');$stmt->execute([$lessonId]);$lesson=$stmt->fetch();if(!$lesson){flash('warning','Please select an available lesson quiz.');redirect('pages/quizzes.php');}$stmt=$pdo->prepare('SELECT id,question,option_a,option_b,option_c,option_d FROM quiz_questions WHERE lesson_id=? ORDER BY id');$stmt->execute([$lessonId]);$questions=$stmt->fetchAll();$page_title='Quiz: '.$lesson['title'];require __DIR__.'/../includes/header.php';
?>
<section class="page-hero page-hero-small"><div class="container"><a class="back-link" href="<?= url('pages/quizzes.php') ?>">← All quizzes</a><span class="eyebrow">KNOWLEDGE CHECK</span><h1><?= e($lesson['title']) ?> <em>quiz.</em></h1><p>Choose the best answer for each question. Your result will be calculated when you submit.</p></div></section><section class="container content-section quiz-container"><?php if(!$questions): ?><div class="empty-state">No questions have been added to this quiz yet.</div><?php else: ?><form method="post" action="<?= url('pages/quiz_submit.php') ?>" class="quiz-form"><?= csrf_field() ?><input type="hidden" name="lesson_id" value="<?= $lessonId ?>"><?php foreach($questions as $i=>$question): ?><fieldset class="question-card"><legend><span class="question-number"><?= $i+1 ?></span><?= e($question['question']) ?></legend><div class="answer-options"><?php foreach(['a','b','c','d'] as $letter): ?><label class="answer-option"><input type="radio" name="answers[<?= (int)$question['id'] ?>]" value="<?= $letter ?>" required><span><?= e($question['option_'.$letter]) ?></span></label><?php endforeach; ?></div></fieldset><?php endforeach; ?><button class="btn btn-primary" type="submit">Submit answers →</button></form><?php endif; ?></section>
